import { Font } from 'fonteditor-core';
import * as wasmBrotli from 'wasm-brotli';

// 确保 fonteditor-core 能找到 Brotli 压缩器来处理 WOFF2
if (typeof window !== 'undefined') {
  window.Brotli = wasmBrotli;
}
export default {
  name: 'FontConverter',
  data() {
    return {
      fontData: null,
      fileName: '',
      sourceFormat: '',
      targetFormat: 'woff2',
      isLoading: false,
      message: ''
    };
  },
  methods: {
    async handleFileUpload(event) {
      const file = event.target.files[0];
      if (!file) return;
      this.fileName = file.name;
      this.sourceFormat = file.name.split('.').pop().toLowerCase();
      this.message = '正在读取文件...';
      try {
        this.fontData = await file.arrayBuffer();
        this.message = '文件读取成功，请选择目标格式并点击转换。';
      } catch (error) {
        this.message = '文件读取失败！';
      }
    },
    async convertFont() {
      if (!this.fontData) return;
      this.isLoading = true;
      this.message = '正在解析并转换字体，请稍候...';
      try {
        // 1. 如果是 WOFF2 转其他格式，先用底层解压（如果 fonteditor-core 自动处理则无需手动干预）
        // fonteditor-core 的 write 方法底层会自动处理 Brotli 压缩，我们只需正常读写
        const font = Font.create(this.fontData, {
          type: this.sourceFormat,
          hinting: true
        });

        // 2. 写入目标格式
        const targetBuffer = font.write({
          type: this.targetFormat,
          toBuffer: true
        });
        this.downloadFont(targetBuffer);
        this.message = '转换成功！文件已开始下载。';
      } catch (error) {
        console.error('字体转换错误:', error);
        this.message = '转换失败，可能是字体过于复杂或包含不支持的格式。';
      } finally {
        this.isLoading = false;
      }
    },
    clearData() {
      this.fontData = null;
      this.fileName = '';
      this.sourceFormat = '';
      this.message = '';
      if (this.$refs.fileInput) this.$refs.fileInput.value = '';
    },
    downloadFont(buffer) {
      const blob = new Blob([buffer], {
        type: 'font/opentype'
      });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      const baseName = this.fileName.substring(0, this.fileName.lastIndexOf('.'));
      a.download = `${baseName}.${this.targetFormat}`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }
  }
};